{"implementation":"import math

def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    if "nodes" not in case or "core_distance" not in case or "distances" not in case:
        raise ValueError("missing required field")

    nodes = case["nodes"]
    cores = case["core_distance"]
    distances = case["distances"]

    if not isinstance(nodes, list) or not nodes:
        raise ValueError("nodes must be a non-empty list")
    if any(type(node) is not str for node in nodes):
        raise ValueError("node identifiers must be strings")
    if len(set(nodes)) != len(nodes):
        raise ValueError("node identifiers must be unique")
    if not isinstance(cores, dict) or set(cores) != set(nodes):
        raise ValueError("core_distance keys must match nodes")
    for node in nodes:
        value = cores[node]
        if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(value) or value < 0:
            raise ValueError("invalid core distance")
    if not isinstance(distances, list):
        raise ValueError("distances must be a list")

    node_set = set(nodes)
    edges = {}
    for item in distances:
        if not isinstance(item, list) or len(item) != 3:
            raise ValueError("each distance must contain two endpoints and a weight")
        left, right, distance = item
        if type(left) is not str or type(right) is not str or left == right:
            raise ValueError("invalid distance endpoints")
        if left not in node_set or right not in node_set:
            raise ValueError("unknown distance endpoint")
        if isinstance(distance, bool) or not isinstance(distance, (int, float)) or not math.isfinite(distance) or distance < 0:
            raise ValueError("invalid distance weight")
        u, v = (left, right) if left < right else (right, left)
        key = (u, v)
        if key in edges:
            raise ValueError("duplicate undirected distance")
        edges[key] = distance

    expected = len(nodes) * (len(nodes) - 1) // 2
    if len(edges) != expected:
        raise ValueError("distance matrix must contain every unordered pair")

    ranked = []
    for (u, v), distance in edges.items():
        weight = max(cores[u], cores[v], distance)
        ranked.append((weight, u, v))
    ranked.sort(key=lambda edge: (edge[0], edge[1], edge[2]))

    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(node):
        while parent[node] != node:
            parent[node] = parent[parent[node]]
            node = parent[node]
        return node

    selected = []
    total = 0
    for weight, u, v in ranked:
        root_u = find(u)
        root_v = find(v)
        if root_u == root_v:
            continue
        if rank[root_u] < rank[root_v]:
            root_u, root_v = root_v, root_u
        parent[root_v] = root_u
        if rank[root_u] == rank[root_v]:
            rank[root_u] += 1
        selected.append([u, v, weight])
        total += weight
        if len(selected) == len(nodes) - 1:
            break

    if len(selected) != len(nodes) - 1:
        raise ValueError("graph is disconnected")
    return {"mst_edges": selected, "total_weight": total}"}
